import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { listSeries } from '../../common/api';
import { seriesUrl } from '../../common/urls';
import SeriesCard from '../components/SeriesCard';
import { failed, t } from '../util';

/** /u/:username/series — a member's series. Their own empty ones show to them only. */
export default class UserSeriesPage extends UserPage {
  series = null;
  shownFor = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    // UserPage shows the user again whenever it refreshes them.
    if (this.shownFor === user.id()) return;
    this.shownFor = user.id();
    this.series = null;
    app.setTitle(extractText(t('profile.nav')) + ' – ' + user.displayName());
    listSeries({
      filter: {
        user: user.id()
      },
      sort: 'latest'
    }).then(({
      data
    }) => {
      this.series = data;
      m.redraw();
    }, e => {
      this.series = [];
      failed(e);
      m.redraw();
    });
  }
  content() {
    const own = this.user === app.session.user && app.forum.attribute('canCreateSeries');
    return m("div", {
      className: "AnthologyUserPage"
    }, own ? m("div", {
      className: "AnthologyHead"
    }, m("span", null), m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(() => import(/* webpackChunkName: 'forum/modals/SeriesEditModal', webpackMode: 'lazy-once' */ '../modals/SeriesEditModal'), {
        onsave: card => m.route.set(seriesUrl(card))
      })
    }, t('directory.new'))) : null, this.series === null ? m(LoadingIndicator, {
      display: "block"
    }) : this.series.length ? m("div", {
      className: "AnthologyGrid"
    }, this.series.map(series => m(SeriesCard, {
      key: series.id,
      series: series
    }))) : m("p", {
      className: "AnthologyEmpty"
    }, t('profile.empty')));
  }
}
flarum.reg.add('ernestdefoe-anthology', 'forum/pages/UserSeriesPage', UserSeriesPage);flarum.reg.addChunkModule('ernestdefoe-anthology:forum/modals/SeriesEditModal', '480', 'ernestdefoe-anthology', 'forum/modals/SeriesEditModal');